create table d_ref_ctpty_mapping(key_ctpty_id string comment '交易对手ID',outside_ctpty_code string comment '交易对手外部唯一码',outside_source string comment '交易对手外部源',created_datetime string comment '创建时间',created_by string comment '创建人',updated_datetime string comment '修改时间',updated_by string comment '修改人',data_time string comment '数据时间') partitioned by (busi_date string comment '业务日期') row format delimited fields terminated by ',' stored as textfile;
